+      uint,                                                    \
+      uint,                                                    \
+      uint,                                                    \
+      uint);                                                   \
+  template [[host_name("median_select_pick_" #T)]] kernel void \
+  median_select_pick<T>(                                       \
+      device T*,                                               \
+      device MedianSelectState*,                               \
+      device uint*,                                            \
+      constant uint&,                                          \
+      constant bool&,                                          \
+      constant bool&,                                          \
+      constant bool&);
